    if (Math.abs(b_vn(x / 20, y / 20 + 9, 805) - 0.5) * 2 < 0.045) v -= 0.24; if (Math.abs(b_vn(x / 10 + 3, y / 12, 810) - 0.5) * 2 < 0.04) v -= 0.16;
    if (Math.abs(y - (106 + 8 * Math.sin(x / 15) + 4 * Math.sin(x / 6.3))) < 0.9) v = 0.88;
