    const V0 = hex('#2f4f3e'), VL = hex('#3a5e4a'), VS = hex('#274234'), CU = hex('#5e3826'), CUL = hex('#7e5038'), CUS = hex('#402418');
    for (let i = 3; i <= 6; i++) b_sombra(R, 158, 102, 86 + i, 80 + i, 0.05);
