  linea(x - r - 2, y, x - r + 1, y - r - 4, P.k); linea(x + r + 2, y, x + r - 1, y - r - 4, P.k);
  for (let k = -2; k <= 2; k++) { const a = Math.round((2 + Math.abs(Math.sin(t * 9 + k * 1.9)) * 3) * s); linea(x + k * 2, y, x + k * 2, y - a, k & 1 ? P.llama : P.brasa); pset(x + k * 2, y - a, P.llamaL); }
