  ar: pal({ roca: '#7c86a0', rocaS: '#5c6684', nieve: '#f4f8ff', nieveS: '#b8c8e0', calima: '#a8bcd0' }), ju: pal({ roca: '#b89a6c', rocaS: '#8a704c', nieve: '#cdb486', nieveS: '#a0865a', calima: '#bcc0c0' }),
