  for (let y = 0; y < 180; y++) for (let x = 0; x < 320; x++) { const calma = y < 50 ? 0.45 : 1, n = 0.5 + (c_ruido(x / 26, y / 18, 101) - 0.5) * calma + (c_um(x, y) - 0.5) * 0.12 + (y - 60) / 500; pset(x, y, M[n < 0.36 ? 0 : n < 0.52 ? 1 : n < 0.7 ? 2 : 3]); }
