    rect(cx - 32, 89, cx + 32, 91, hex('#e4d6b8')); rect(cx - 32, 92, cx + 32, 92, hex('#7a6850')); rect(cx - 31, 93, cx + 31, 93, hex('#9a8262')); pset(cx - 32, 89, hex('#fbf2dc'));
    // la misma maceta de albahaca en el alféizar de las tres
