  for (let x = 0; x < 320; x++) { const i = (x + 300) % 12, z = Math.abs(i - 6); for (let y = 156; y <= 164; y++) { const j = Math.abs(y - 160); if (z + j === 4) pset(x, y, P.oro); else if (z + j === 1 || (z === 0 && j === 0)) pset(x, y, P.oroL); } pset(x, 154, P.oroS); pset(x, 166, P.oroS); }
