  for (const [cx, cy, s] of [[x0 + 10, y0 + 49, 0], [x0 + 27, y0 + 44, 1.7]]) for (let j = 0; j < 6; j++) { const u = (t * 0.22 + j / 6 + s) % 1; R.disco(cx + u * 9 + Math.sin(u * 6 + j) * 1.2, cy - u * 15, 0.8 + u * 1.6, u < 0.5 ? hex('#8e9090') : hex('#a6a8a4')); }
