      if (y === ya) c = tj; else if (fx === 0) c = tj; else if (y === ya + 1 && h(x >> 2, f, 36) < 0.5) c = t3; else if (h(x >> 3, y + n * 7, 36) < 0.13) c = tv; else if (h(x, y, 37) < 0.03) c = t3;
