  R.rect(281, 129, 291, 130, P.barroC[0]); R.rect(282, 128, 290, 128, P.k); R.rect(282, 144, 290, 152, P.k); R.rect(283, 143, 289, 143, P.k); R.rect(280, 153, 293, 154, AD[1]);
