  for (const [x, y] of [[212, 142], [222, 144]]) { R.rect(x - 3, y - 2, x + 3, y, P.barroC[2]); R.rect(x - 3, y - 2, x + 3, y - 2, P.barroC[3]); R.rect(x - 2, y + 1, x + 2, y + 1, P.barroC[0]); R.rect(x - 2, y - 2, x + 2, y - 2, hex('#e8d078')); }
