  lab: '#e6eaee', labS: '#ccd4dc', labL: '#f6f8fa', labD: '#a8b2be', epoxi: '#b8c4cc', epoxiS: '#9eacb6', epoxiL: '#d2dce2', epoxiD: '#7e8e9a',
