  // el gato, sentado en la tarima, que mira el tablero; y el polvo en la luz
  if (o.gato !== false) { for (let i = -7; i <= 7; i++) if (i & 1) pset(L.gato[0] + i + 2, L.gato[1] + 1, K.tarimaD); g_gato(R, L.gato[0], L.gato[1], t, { dir: 1 }); }
