  { const [x0, y0] = G.reloj, c = hex('#2a3a2a'), m = 42 + Math.floor(t / 5) % 10; d_num(R, x0 + 9, y0 + 6, 10, c); d_num(R, x0 + 21, y0 + 6, m, c); if (Math.floor(t * 2) % 2 === 0) { pset(x0 + 18, y0 + 7, c); pset(x0 + 18, y0 + 9, c); } }
