    rect(S.rampa - 7, y0, S.rampa - 1, y1, K.k); for (let y = y0; y <= y1; y++) rect(S.rampa - 6, y, S.rampa - 2, y, (y - y0) % 6 < 2 ? K.aceroL : (y - y0) % 6 < 4 ? K.acero : K.aceroS);
