    const bx = S.rampa + 14; rect(bx - 1, y0 - 4, 319, y1 + 4, K.k); for (let y = y0 - 3; y <= y1 + 3; y++) for (let x = bx; x < 320; x++) pset(x, y, (x - bx) % 8 === 7 || (y - y0 + 3) % 8 === 7 ? hex('#b4c8c8') : h((x - bx) >> 3, (y - y0 + 3) >> 3, 394 + k) < 0.3 ? hex('#d2e2e2') : hex('#e2eeee'));
