  for (const cx of G.libres) { for (let i = -9; i <= 9; i++) { const top = G.respaldo + Math.round(Math.pow(Math.abs(i) / 11, 2.4) * 4); pset(cx + i, top + 1, hex('#e0b070')); if (Math.abs(i) < 8 && (i + 40) % 2) pset(cx + i, top + 4, hex('#c85a50')); } }
