  rect(x - 13, y - 6, x + 13, y - 6, P.k); rect(x - 8, y - 11, x + 7, y - 7, T1[1]); rect(x - 8, y - 11, x - 2, y - 7, T0[1]); for (let i = -8; i <= 7; i += 3) rect(x + i, y - 11, x + i, y - 7, P.junta); rect(x - 9, y - 11, x - 9, y - 7, P.k); rect(x + 8, y - 11, x + 8, y - 7, P.k);
